import itertools
import random
import sys

sys.path.insert(0, "/home/c/brix2/b/task100")
import relay


def brute_paths(nodes, links, src):
    # Enumerate every simple path over up links; min (cost, sequence).
    adj = {}
    cost = {}
    for l in links:
        if l["up"]:
            adj.setdefault(l["from"], []).append(l["to"])
            cost[(l["from"], l["to"])] = l["cost"]
    best = {n: None for n in nodes}
    best[src] = (0, (src,))

    def dfs(u, path, c):
        for v in adj.get(u, ()):
            if v in path:
                continue
            np = path + (v,)
            nc = c + cost[(u, v)]
            key = (nc, np)
            if best[v] is None or key < best[v]:
                best[v] = key
            dfs(v, np, nc)

    dfs(src, (src,), 0)
    return best


def rand_topo(rng):
    V = rng.randint(1, 7)
    names = [chr(0x41 + i) for i in range(V)]
    links = []
    for u, v in itertools.permutations(names, 2):
        if rng.random() < 0.4:
            links.append({"from": u, "to": v, "cost": rng.randint(1, 3),
                          "up": rng.random() < 0.85,
                          "bandwidth": 1, "latency": 0})
    return names, links


def main():
    rng = random.Random(555)
    bad = 0
    for t in range(20000):
        names, links = rand_topo(rng)
        adj = {}
        for l in links:
            if l["up"]:
